def transform(grid):
    """Overlay aligned pattern halves around the solid center divider.

    The common background color is retained wherever either panel has a
    foreground mark; cells that are background in both panels become 3.
    """
    h, w = len(grid), len(grid[0])
    separators = [c for c in range(w) if len({row[c] for row in grid}) == 1]
    sep = min(separators, key=lambda c: abs(c - (w - 1) / 2))
    left = [row[:sep] for row in grid]
    right = [row[sep + 1:] for row in grid]
    width = min(len(left[0]), len(right[0]))

    def dominant(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    left_bg, right_bg = dominant(left), dominant(right)
    background = left_bg if left_bg == right_bg else left_bg
    return [
        [3 if left[r][c] == left_bg and right[r][c] == right_bg else background
         for c in range(width)]
        for r in range(h)
    ]
